<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateVariable\Domain\Gateway;

use Civi\Lughauth\Features\Document\TemplateVariable\Domain\TemplateVariable;

class TemplateVariableCursor
{
    public const string CODE_ASC = 'code';
    public const string CODE_DESC = '-code';

    public function __construct(
        private int $limit,
        private ?string $sinceUid = null,
        private ?string $sinceCode = null,
        private ?array $order = null,
    ) {
    }
    public function next(TemplateVariable $templateVariable, ?int $size): TemplateVariableCursor
    {
        $next = clone $this;
        $next->sinceUid = $templateVariable->uid();
        $next->sinceCode = $templateVariable->getCode();
        $next->limit = $size ?? $this->limit;
        return $next;
    }
    public function limit(): int
    {
        return $this->limit;
    }
    public function sinceUid(): ?string
    {
        return $this->sinceUid;
    }
    public function sinceCode(): ?string
    {
        return $this->sinceCode;
    }
    public function order(): ?array
    {
        return $this->order;
    }
}
